260:       Object.keys(this.marketData).forEach((symbol) => {
261:         const asset = this.marketData[symbol];
262:         
263:         // Mutual funds change slower than stocks
264:         const volatility = asset.type === 'stock' ? 0.005 : 0.001;
265:         const percentChange = (Math.random() - 0.49) * 2 * volatility; // slightly positive drift
266:         
267:         const newPrice = asset.price * (1 + percentChange);
268:         const roundedPrice = asset.type === 'stock' 
269:           ? Math.round(newPrice * 100) / 100 
270:           : Math.round(newPrice * 10000) / 10000;
271:           
272:         const change = roundedPrice - asset.prevClose;
273:         const changePercent = asset.prevClose > 0 ? (change / asset.prevClose) * 100 : 0;
274: 
275:         this.marketData[symbol] = {
276:           ...asset,
277:           price: roundedPrice,
278:           change,
279:           changePercent,
280:           lastUpdated: new Date().toLocaleTimeString()
281:         };
282:       });
283: 
284:       this.notify();
285:     }, 3000);
286:   }
