309:   // Fetch real NAV prices from Finnomena via AllOrigins CORS proxy
310:   private async fetchFinnomenaFundNav(symbol: string): Promise<{ price: number; prevClose: number } | null> {
311:     const sym = symbol.toUpperCase().trim();
312:     try {
313:       const url = `https://api.finnomena.com/fund/api/v1/fund/detail/NAV?symbol=${sym}`;
314:       const proxyUrl = `https://api.allorigins.win/get?url=${encodeURIComponent(url)}`;
315:       
316:       const response = await fetch(proxyUrl);
317:       if (!response.ok) return null;
318:       
319:       const data = await response.json();
320:       const rawJson = JSON.parse(data.contents);
321:       if (Array.isArray(rawJson) && rawJson.length > 0) {
322:         const latest = rawJson[rawJson.length - 1];
323:         const previous = rawJson.length > 1 ? rawJson[rawJson.length - 2] : latest;
324:         
325:         const price = Number(latest.nav);
326:         const prevClose = Number(previous.nav);
327:         if (!isNaN(price) && !isNaN(prevClose)) {
328:           return { price, prevClose };
329:         }
330:       }
331:       return null;
332:     } catch (e) {
333:       console.error(`Failed to fetch Finnomena NAV for ${symbol}`, e);
334:       return null;
335:     }
336:   }
