390:   // Fetch prices of multiple assets using Gemini API with Google Search grounding
391:   private async fetchPricesViaGemini(symbols: string[]): Promise<Record<string, { price: number; prevClose: number }> | null> {
392:     const apiKey = this.config.geminiApiKey;
393:     if (!apiKey) return null;
394: 
395:     const model = this.config.selectedModel || 'gemini-3.1-flash-lite';
396:     
397:     // Group symbols by their asset type dynamically to help Google Search target correct endpoints
398:     const stockSymbols: string[] = [];
399:     const fundSymbols: string[] = [];
400:     
401:     symbols.forEach(sym => {
402:       const asset = this.marketData[sym];
403:       if (asset?.type === 'fund') {
404:         fundSymbols.push(sym);
405:       } else {
406:         stockSymbols.push(sym);
407:       }
408:     });
409: 
410:     const prompt = `You are a real-time financial price lookup assistant. Use Google Search to find the current stock prices (last close or regular market price) for stocks, and the latest NAV prices (Net Asset Value) for mutual funds, along with their previous day's closing/NAV prices.
411: The list of STOCKS to look up is: ${stockSymbols.join(', ')}. (For Thai stocks, search on the Stock Exchange of Thailand, and for US stocks, search US exchanges).
412: The list of MUTUAL FUNDS to look up is: ${fundSymbols.join(', ')}. (For Thai mutual funds, search specifically for their latest NAV prices on finnomena.com by typing e.g. "SYMBOL site:finnomena.com/fund". This is critical to get the correct NAV value, e.g. around 7.38 for KFGG-A, instead of looking up other share classes or outdated info).
413: Reply ONLY with a valid JSON object matching this schema: { "TICKER": { "price": number, "prevClose": number } }. 
414: Do not include any markdown formatting, backticks, or explanatory text - return ONLY the raw JSON string. 
415: Ensure keys match the input symbols exactly (e.g. if the input is K-EQD, the key in JSON must be "K-EQD", and for KFGG-A it must be "KFGG-A").`;
416: 
417:     try {
418:       const response = await fetch(
419:         `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
420:         {
421:           method: 'POST',
422:           headers: { 'Content-Type': 'application/json' },
423:           body: JSON.stringify({
424:             contents: [{ parts: [{ text: prompt }] }],
425:             tools: [{ googleSearch: {} }] // Enable Google Search grounding!
426:           })
427:         }
428:       );
429: 
430:       if (!response.ok) {
431:         const errorText = await response.text();
432:         console.error(`Gemini API Price Fetch error status ${response.status}:`, errorText);
433:         localStorage.setItem('portfolio_tracker_price_fetch_error', `Gemini API Error ${response.status}: ${errorText}`);
434:         return null;
435:       }
436: 
437:       const data = await response.json();
438:       let text = data.candidates?.[0]?.content?.parts?.[0]?.text || '';
439:       
440:       // ดึงเฉพาะส่วนที่เป็น JSON ด้วย Regex ป้องกันกรณีโมเดลใส่ข้อความอธิบายอื่นมาด้วย
441:       const jsonMatch = text.match(/\{[\s\S]*\}/);
442:       if (jsonMatch) {
443:         text = jsonMatch[0];
444:       }
445:       
446:       const parsed = JSON.parse(text);
447:       localStorage.removeItem('portfolio_tracker_price_fetch_error'); // Clear error on success
448:       return parsed;
449:     } catch (e: any) {
450:       console.error('Failed to fetch prices via Gemini Google Search', e);
451:       localStorage.setItem('portfolio_tracker_price_fetch_error', `Fetch error: ${e.message || e}`);
452:       return null;
453:     }
454:   }
