456:   // Method to fetch real prices from Gemini (first) or Yahoo Finance/Finnomena (second)
457:   private async fetchRealPrices() {
458:     if (this.config.useMock) return;
459: 
460:     // จำกัดการดึงราคาห้ามเกิน 1 ครั้งต่อ 65 วินาที เพื่อไม่ให้เกินโควต้า Google Search Grounding ของสายฟรี
461:     const lastFetch = localStorage.getItem('portfolio_tracker_last_fetch_time');
462:     const now = Date.now();
463:     if (lastFetch && now - Number(lastFetch) < 65000) {
464:       console.log('Skipping real-time price fetch to respect Gemini Search Grounding rate limit (1 request/min)');
465:       return;
466:     }
467:     localStorage.setItem('portfolio_tracker_last_fetch_time', now.toString());
468: 
469:     console.log('Fetching real-time prices...');
470:     
471:     // ดึงเฉพาะตัวย่อที่มีการถือครองอยู่จริงในพอร์ตมาอัปเดตก่อน เพื่อจำกัดขนาดคำสั่งให้ AI ไม่สับสน
472:     let symbols = Object.keys(this.marketData);
473:     const savedHoldings = localStorage.getItem('portfolio_tracker_holdings');
474:     if (savedHoldings) {
475:       try {
476:         const holdingsList = JSON.parse(savedHoldings);
477:         if (Array.isArray(holdingsList) && holdingsList.length > 0) {
478:           const activeSymbols = new Set<string>();
479:           holdingsList.forEach((h: any) => {
480:             if (h && h.symbol) activeSymbols.add(h.symbol.toUpperCase().trim());
481:           });
482:           if (activeSymbols.size > 0) {
483:             symbols = Array.from(activeSymbols);
484:           }
485:         }
486:       } catch (e) {
487:         console.error('Failed to parse holdings for active symbols filter', e);
488:       }
489:     }
490:     
491:     // Stage 1: Try fetching via Gemini API Google Search grounding
492:     const successfulSymbols = new Set<string>();
493:     
494:     if (this.config.geminiApiKey && !this.config.useFreePriceMode) {
495:       console.log('Attempting to fetch prices via Gemini Google Search...');
496:       const geminiData = await this.fetchPricesViaGemini(symbols);
497:       if (geminiData) {
498:         console.log('Successfully fetched prices via Gemini Google Search:', geminiData);
499:         let updated = false;
500:         symbols.forEach((symbol) => {
501:           const sym = symbol.toUpperCase();
502:           const match = geminiData[sym] || geminiData[symbol];
503:           
504:           // ป้องกันราคา 0 หรือค่าว่างที่เกิดจากข้อผิดพลาดของผลการค้นหา
505:           if (match && typeof match.price === 'number' && match.price > 0 && typeof match.prevClose === 'number' && match.prevClose > 0) {
506:             const asset = this.marketData[sym];
507:             const change = match.price - match.prevClose;
508:             const changePercent = match.prevClose > 0 ? (change / match.prevClose) * 100 : 0;
509:             
510:             this.marketData[sym] = {
511:               ...asset,
512:               price: match.price,
513:               prevClose: match.prevClose,
514:               change,
515:               changePercent,
516:               lastUpdated: new Date().toLocaleTimeString()
517:             };
518:             successfulSymbols.add(sym);
519:             updated = true;
520:           }
521:         });
522:         if (updated) {
523:           this.notify();
524:         }
525:       }
526:     }
527: 
528:     // Stage 2: Fallback to Yahoo Finance and Finnomena API for symbols not successfully fetched by Gemini
