### How the cache is now used

```ts
// Inside financeApi.ts (excerpt)
public async fetchSingleAssetPrice(symbol: string) {
  const sym = symbol.toUpperCase().trim();
  if (!sym) return null;

  const cacheKey = `price:${sym}`;
  const cached = await getCache(cacheKey);
  if (cached) return { price: cached.price, prevClose: cached.prevClose };

  const isFund = sym.includes('-') || sym.length > 6 || sym.includes('RMF') || sym.includes('SSF');
  try {
    let result;
    if (isFund) {
      const finData = await this.fetchFinnomenaFundNav(sym);
      result = finData ?? await this.fetchYahooPrice(sym);
    } else {
      result = await this.fetchYahooPrice(sym);
    }
    if (result) {
      await setCache(cacheKey, result, 5 * 60 * 1000); // 5 min TTL
      return result;
    }
  } catch (e) {
    console.warn('fetchSingleAssetPrice error, attempting fallback', e);
  }
  // Final fallback to any cached asset data
  const asset = this.getAsset(sym);
  return asset ? { price: asset.price, prevClose: asset.prevClose } : null;
}
```

