120:       if (holdings.length < 3) diversificationScore -= 30;
121:       else if (holdings.length < 5) diversificationScore -= 15;
122:       
123:       // Penalty for missing asset types
124:       if (assetTypeMap.stock === 0 || assetTypeMap.fund === 0) {
125:         diversificationScore -= 20;
126:       }
127:       
128:       diversificationScore = Math.max(10, Math.min(100, Math.round(diversificationScore)));
129:     }
130: 
131:     // Generate Warnings
132:     const warnings: string[] = [];
133:     if (holdings.length > 0) {
134:       if (assetTypeMap.stock / totalValue > 0.85) {
135:         warnings.push('พอร์ตของคุณมีสัดส่วนหุ้นสูงมาก (>85%) ซึ่งมีความผันผวนสูงมาก ควรเพิ่มกองทุนรวมตราสารหนี้หรือกองทุนรวมต่างประเทศเพื่อลดความเสี่ยง');
136:       }
137:       if (sectorAllocations.length > 0 && sectorAllocations[0].percentage > 50) {
138:         warnings.push(`มีการกระจุกตัวในกลุ่มอุตสาหกรรม "${sectorAllocations[0].sector}" มากเกินไป (${sectorAllocations[0].percentage.toFixed(1)}%) แนะนำกระจายไปยังอุตสาหกรรมอื่น`);
139:       }
140:       if (holdings.length <= 2) {
141:         warnings.push('พอร์ตของคุณมีจำนวนสินทรัพย์น้อยเกินไป (ต่ำกว่า 3 ชิ้น) ควรเพิ่มความหลากหลายเพื่อลดความเสี่ยงเฉพาะตัวของหุ้นแต่ละตัว');
142:       }
143:       
144:       // Individual holding concentration warning
145:       holdings.forEach(h => {
146:         const assetPrice = currentPrices[h.symbol.toUpperCase()]?.price || h.avgCost;
147:         const val = h.quantity * assetPrice;
148:         if (totalValue > 0 && (val / totalValue) > 0.4) {
149:           warnings.push(`หุ้น/กองทุน "${h.symbol.toUpperCase()}" มีสัดส่วนมากกว่า 40% ของพอร์ตทั้งหมด ความผันผวนของสินทรัพย์นี้จะส่งผลกระทบต่อพอร์ตค่อนข้างสูง`);
150:         }
151:       });
152:     } else {
153:       warnings.push('ยังไม่มีรายการลงทุนในพอร์ต เริ่มต้นเพิ่มรายการหุ้นหรือกองทุนรวมได้เลย!');
154:     }
155: 
156:     // Generate Dynamic Suggestions
157:     const suggestions = RECOMMENDATION_ITEMS.filter(item => {
158:       // Don't recommend what they already own
159:       const ownsItem = holdings.some(h => h.symbol.toUpperCase() === item.symbol);
160:       if (ownsItem) return false;
161: 
162:       // Customize suggestions based on portfolio needs
163:       if (riskLevel === 'สูง' && item.type === 'stock' && item.symbol === 'NVDA') {
164:         return false; // Don't suggest high-risk stock if already high risk, suggest funds instead
165:       }
166:       if (riskLevel === 'ต่ำ' && item.type === 'stock' && item.symbol === 'NVDA') {
167:         return false; // Low risk target shouldn't buy tech growth stocks
168:       }
169:       return true;
170:     }).slice(0, 3); // Pick top 3 recommendations
171: 
172:     return {
173:       totalValue,
174:       totalCost,
175:       totalGainLoss,
176:       totalGainLossPercent,
177:       riskScore,
178:       riskLevel,
179:       diversificationScore,
180:       sectorAllocations,
181:       assetAllocations,
182:       warnings,
183:       suggestions
184:     };
185:   }
