### 3️⃣ การเรียกใช้จาก UI (React ตัวอย่าง)

```tsx
// src/components/PortfolioSummary.tsx
import { useEffect, useState } from 'react';
import { calculatePortfolioValue } from '../portfolioService';

export default function PortfolioSummary({ holdings }) {
  const [value, setValue] = useState<number | null>(null);

  useEffect(() => {
    async function compute() {
      const total = await calculatePortfolioValue(holdings);
      setValue(total);
    }
    compute();
  }, [holdings]);

  return (
    <div className="portfolio-summary">
      <h2>มูลค่าพอร์ต</h2>
      {value === null ? (
        <p>กำลังโหลด…</p>
      ) : (
        <p>฿ {value.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
      )}
    </div>
  );
}
```

เมื่อผู้ใช้เปิดหน้าแสดงพอร์ต UI จะเรียก `calculatePortfolioValue` → ใช้ cache ตามที่ได้ตั้งค่า → ลดเวลาโหลดและจำนวนคอล์ API

